"""Color 16x16 weather icons rendered from Noto Color Emoji.

Icons are pre-rendered from the Noto Color Emoji font (SIL OFL).
https://fonts.google.com/noto/specimen/Noto+Color+Emoji
"""

from typing import Dict

from PIL import Image

_SUN_HEX = ""

_PARTIAL_CLOUD_HEX = ""

_CLOUD_HEX = ""

_LIGHT_RAIN_HEX = ""

_RAIN_HEX = ""

_SNOW_HEX = ""

_THUNDERSTORM_HEX = ""

_FOG_HEX = ""


def _hex_to_image(hex_data: str) -> Image.Image:
    """Convert hex-encoded RGB data to a 16x16 PIL Image."""
    return Image.frombytes("RGB", (16, 16), bytes.fromhex(hex_data))


# Build icon images from embedded data
_ICON_IMAGES: Dict[str, Image.Image] = {
    "sun": _hex_to_image(_SUN_HEX),
    "partial_cloud": _hex_to_image(_PARTIAL_CLOUD_HEX),
    "cloud": _hex_to_image(_CLOUD_HEX),
    "light_rain": _hex_to_image(_LIGHT_RAIN_HEX),
    "rain": _hex_to_image(_RAIN_HEX),
    "snow": _hex_to_image(_SNOW_HEX),
    "thunderstorm": _hex_to_image(_THUNDERSTORM_HEX),
    "fog": _hex_to_image(_FOG_HEX),
}


# Map WMO weather codes to icon keys
WMO_CODE_TO_ICON: Dict[int, str] = {
    0: "sun",
    1: "partial_cloud",
    2: "partial_cloud",
    3: "cloud",
    45: "fog",
    48: "fog",
    51: "light_rain",
    53: "light_rain",
    55: "light_rain",
    56: "light_rain",
    57: "light_rain",
    61: "rain",
    63: "rain",
    65: "rain",
    66: "rain",
    67: "rain",
    71: "snow",
    73: "snow",
    75: "snow",
    77: "snow",
    80: "rain",
    81: "rain",
    82: "rain",
    85: "snow",
    86: "snow",
    95: "thunderstorm",
    96: "thunderstorm",
    99: "thunderstorm",
}


def get_weather_icon_image(code: int) -> Image.Image:
    """Get the 16x16 color RGB icon for a WMO weather code."""
    icon_key = WMO_CODE_TO_ICON.get(code, "cloud")
    return _ICON_IMAGES[icon_key].copy()
